import { Component, computed, input } from '@angular/core';
import { IconComponent } from './icon.component';
import { TranslatePipe } from './translate.pipe';

export type StatusValue =
    | 'success'
    | 'warning'
    | 'approval'
    | 'error'
    | 'info'
    | 'neutral';

/** Locale keys that name each booking status for assistive technology */
const STATUS_LABELS: Record<StatusValue, string> = {
    success: 'COMMON.APPROVED',
    warning: 'COMMON.STATUS_PENDING',
    approval: 'COMMON.APPROVAL_REQUIRED',
    error: 'COMMON.DECLINED',
    info: 'COMMON.WAITLISTED',
    neutral: 'COMMON.STATE_DONE',
};

@Component({
    selector: 'status-pill',
    template: `
        <div
            class="border-base-200 flex items-center space-x-2 rounded-full border px-2 py-1 text-base font-medium"
            [class.text-black]="status() !== 'neutral'"
            [class.text-base-content]="status() === 'neutral'"
            [class.bg-success-light]="status() === 'success'"
            [class.bg-warning-light]="status() === 'warning'"
            [class.bg-approval-light]="status() === 'approval'"
            [class.bg-error-light]="status() === 'error'"
            [class.bg-info-light]="status() === 'info'"
            [class.bg-base-200]="status() === 'neutral'"
        >
            <div
                class="flex h-5 w-5 items-center justify-center rounded-full"
                [class.text-success]="status() === 'success'"
                [class.text-warning]="status() === 'warning'"
                [class.text-approval]="status() === 'approval'"
                [class.text-error]="status() === 'error'"
                [class.text-info]="status() === 'info'"
                [class.text-base-content]="status() === 'neutral'"
                [class.opacity-40]="status() === 'neutral'"
            >
                <icon
                    class="text-2xl"
                    [label]="label() || (status_label() | translate)"
                >
                    @switch (status()) {
                        @case ('success') {
                            check_circle
                        }
                        @case ('error') {
                            cancel
                        }
                        @case ('neutral') {
                            block
                        }
                        @case ('info') {
                            info
                        }
                        @case ('approval') {
                            gavel
                        }
                        @default {
                            warning
                        }
                    }
                </icon>
            </div>
            <div [class.opacity-40]="status() === 'neutral'">
                <ng-content></ng-content>
            </div>
        </div>
    `,
    styles: [``],
    imports: [IconComponent, TranslatePipe],
})
export class StatusPillComponent {
    public readonly status = input<string>(undefined);
    /** Name of the status icon. Defaults to the name of `status`. */
    public readonly label = input('');
    /** Locale key for the name of the current status */
    public readonly status_label = computed(
        () => STATUS_LABELS[this.status() as StatusValue] ?? '',
    );
}
